__mod["card"] = function(...)
-- The small status card in the game detail ("detail" slot). Text and chips only; never shows what was randomized.
local games = require("games")

local M = {}

--- Builds the tree for a detail.game payload ({ system, code, sha256, title }).
function M.build(t, game)
  local supported = games.supported(game.system, game.code)
  local title = type(game.title) == "string" and game.title ~= "" and game.title or nil
  local kids = {
    { type = "row", gap = 8, align = "center", children = {
      { type = "badge", id = "status", text = supported and t("supported") or t("not_supported"),
        tone = supported and "ok" or "neutral" },
    } },
  }
  if supported then
    kids[#kids + 1] = { type = "text", id = "line", text = title and t("supported_line", { title = title }) or t("slot_note"), style = "body" }
    if title then kids[#kids + 1] = { type = "text", id = "slot", text = t("slot_note"), style = "meta" } end
  else
    kids[#kids + 1] = { type = "text", id = "line", style = "body",
      text = title and t("unsupported_line", { title = title }) or t("unsupported_generic") }
  end
  return { type = "section", id = "randomizer", title = t("title"), children = kids }
end

return M

end
__mod["games"] = function(...)
-- Games the engine supports (main games of Gen 1 to 7), as the text identifiers Uzume reads from the game file
-- (hub gamecode.go): gb/gbc = header title, gba/nds = 4-character game code, 3ds = 16-digit program ID.
-- Codes follow the manifest rule: globs, `*` any run, `?` one character, case-insensitive.
local M = {}

M.games = {
  -- Gen 1: header title at 0x134 (Red, Blue, Green in all language versions; Yellow is CGB-flagged, so Uzume
  -- keeps only 11 characters of its title, hence the glob).
  { system = "gb", codes = { "POKEMON RED", "POKEMON BLUE", "POKEMON GREEN", "POKEMON YEL*" } },
  -- Gen 2: header titles (11 characters, CGB-flagged). Yellow is listed again because Uzume may file it as gbc.
  { system = "gbc", codes = { "POKEMON_GLD", "POKEMON_SLV", "PM_CRYSTAL", "POKEMON YEL*" } },
  -- Gen 3: Ruby, Sapphire, Emerald, FireRed, LeafGreen (all language versions).
  { system = "gba", codes = {
    "AXVD", "AXVE", "AXVF", "AXVI", "AXVJ", "AXVS",
    "AXPD", "AXPE", "AXPF", "AXPI", "AXPJ", "AXPS",
    "BPED", "BPEE", "BPEF", "BPEI", "BPEJ", "BPES", "BPET",
    "BPRD", "BPRE", "BPRF", "BPRI", "BPRJ", "BPRS",
    "BPGD", "BPGE", "BPGF", "BPGI", "BPGJ", "BPGS",
  } },
  -- Gen 4 and 5: Diamond, Pearl, Platinum, HeartGold, SoulSilver, Black, White, Black 2, White 2.
  { system = "nds", codes = {
    "ADAD", "ADAE", "ADAF", "ADAI", "ADAJ", "ADAK", "ADAS",
    "APAD", "APAE", "APAF", "APAI", "APAJ", "APAK", "APAS",
    "CPUD", "CPUE", "CPUF", "CPUI", "CPUJ", "CPUK", "CPUS",
    "IPKD", "IPKE", "IPKF", "IPKI", "IPKJ", "IPKK", "IPKS",
    "IPGD", "IPGE", "IPGF", "IPGI", "IPGJ", "IPGK", "IPGS",
    "IRBD", "IRBF", "IRBI", "IRBJ", "IRBK", "IRBO", "IRBS",
    "IRAD", "IRAF", "IRAI", "IRAJ", "IRAK", "IRAO", "IRAS",
    "IRED", "IREF", "IREI", "IREJ", "IREK", "IREO", "IRES",
    "IRDD", "IRDF", "IRDI", "IRDJ", "IRDK", "IRDO", "IRDS",
  } },
  -- Gen 6 and 7: program ID of the base game (X, Y, Omega Ruby, Alpha Sapphire, Sun, Moon, Ultra Sun, Ultra Moon).
  { system = "3ds", codes = {
    "0004000000055D00", "0004000000055E00", "000400000011C400", "000400000011C500",
    "0004000000164800", "0004000000175E00", "00040000001B5000", "00040000001B5100",
  } },
}

local function glob_match(pattern, text)
  local lua = pattern:upper():gsub("[%^%$%(%)%%%.%[%]%+%-]", "%%%0"):gsub("%*", ".*"):gsub("%?", ".")
  return text:upper():match("^" .. lua .. "$") ~= nil
end

--- True when the game (system, code as in the host event detail.game) is on the list.
function M.supported(system, code)
  if type(system) ~= "string" or type(code) ~= "string" or code == "" then return false end
  for _, entry in ipairs(M.games) do
    if entry.system == system then
      for _, c in ipairs(entry.codes) do
        if glob_match(c, code) then return true end
      end
    end
  end
  return false
end

return M

end
__mod["main"] = function(...)
-- Entry module of the Randomizer plugin: hands presets and supported games to Uzume (fb.variants.register)
-- and shows a status card in the game detail. Uzume draws the dialogs, the variant list and the builds.
local presets = require("presets")
local games = require("games")
local card = require("card")

local fb = fb
local t = fb.i18n.t

fb.log.info(t("loaded", { version = (fb.plugin and fb.plugin.version) or "?" }))

local function preset_list()
  local list = {}
  for _, id in ipairs(presets.order) do
    list[#list + 1] = {
      id = id,
      label = t("preset_" .. id .. "_label"),
      hint = t("preset_" .. id .. "_hint"),
      settings = presets.settings[id],
    }
  end
  return list
end

local function game_list()
  local list = {}
  for _, entry in ipairs(games.games) do
    local codes = {}
    for i, c in ipairs(entry.codes) do codes[i] = c end
    list[#list + 1] = { system = entry.system, codes = codes }
  end
  return list
end

-- Once at load, also in the shell context (no game running).
local ok, err = pcall(fb.variants.register, { engine = "randomizer", presets = preset_list(), games = game_list() })
if not ok then fb.log.error(t("register_failed", { error = tostring(err) })) end

fb.events.on("fb", "detail.game", function(game)
  if type(game) ~= "table" then
    fb.ui.clear("detail")
    return
  end
  fb.ui.set("detail", card.build(t, game))
end)

end
